{"content":"void vs_media_stream_close(struct vs_media_stream_s *stream)
{
  int i;

  if (stream == NULL)
    {
      return;
    }

  if (stream->fd >= 0)
    {
      if (stream->streaming)
        {
          int type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

          ioctl(stream->fd, VIDIOC_STREAMOFF, (unsigned long)&type);
          stream->streaming = false;
        }

      for (i = 0; i < VS_MEDIA_NBUFFERS; i++)
        {
          if (stream->addr[i] != NULL)
            {
              munmap(stream->addr[i], stream->buflen[i]);
              stream->addr[i] = NULL;
            }
        }

      /* Hand the driver's allocation back explicitly rather than relying on
       * close(), for the same reason the one-shot path does: an internal
       * buffer count that drifts across open/close cycles only shows up after
       * many sessions.
       */

      {
        struct v4l2_requestbuffers req;

        memset(&req, 0, sizeof(req));
        req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        req.memory = V4L2_MEMORY_MMAP;
        req.count  = 0;
        ioctl(stream->fd, VIDIOC_REQBUFS, (unsigned long)&req);
      }

      close(stream->fd);
      stream->fd = -1;
    }

  if (stream->delivered != 0 || stream->malformed != 0)
    {
      printf("vs_media: stream closed, %lu frames, %lu malformed\n",
             (unsigned long)stream->delivered,
             (unsigned long)stream->malformed);
    }

  free(stream);
}
"}

{"content":"                        const char *what)
{
  pthread_attr_t attr;
  struct sched_param param;
  int ret;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, CONFIG_VS_SOCIAL_STACKSIZE);

  /* Above the UI, below the network stack, matching the layout vs_types.h
   * describes: these threads move media and must not be held off by a redraw.
   */

  param.sched_priority = VS_PRIORITY_VOICE;
  pthread_attr_setschedparam(&attr, &param);

  ret = pthread_create(thread, &attr, entry, NULL);
  pthread_attr_destroy(&attr);

  if (ret != 0)
    {
      printf("%s: cannot start %s thread: %d\n", SOCIAL_TAG, what, ret);
      return -ret;
    }

  return 0;
}

static void *social_session_worker(void *arg)
{
  bool finalize;
  bool aborting;
  int ret;

  (void)arg;

  memset(&g_social.session, 0, sizeof(g_social.session));

  ret = vs_cloud_social_open(&g_social.session);
  if (ret < 0)
    {
      const char *why;

      switch (ret)
        {
          case -EBUSY:
            why = "云端仍有未结束的会话";
            break;
          case -ENODATA:
            why = "还没有配置社交云地址";
            break;
          default:
            why = NULL;
            break;
        }

      printf("%s: open failed: %d\n", SOCIAL_TAG, ret);
      social_post(VS_APP_EVENT_SOCIAL_START_FAILED, ret, VS_EMOTION_NONE, 0,
                  why);
      goto done;
    }

  /* Devices next.  Camera first, because it is the one that can be owned by
   * something else and is therefore the likelier failure.
   */

  ret = vs_media_stream_open(&g_social.camera, CONFIG_VS_SOCIAL_IMAGE_WIDTH,
                             CONFIG_VS_SOCIAL_IMAGE_HEIGHT);
  if (ret < 0)
    {
      printf("%s: camera unavailable: %d\n", SOCIAL_TAG, ret);
      social_post(VS_APP_EVENT_SOCIAL_START_FAILED, ret, VS_EMOTION_NONE, 0,
                  ret == -EBUSY ? "相机正被其他功能占用" : "相机打不开");
      goto close_session;
    }

  g_social.mic = vs_audio_capture_open(AGENT_AUDIO_CAPTURE_DEV,
                                       SOCIAL_AUDIO_RATE,
                                       SOCIAL_AUDIO_CHANNELS,
                                       SOCIAL_AUDIO_BITS);
  if (g_social.mic == NULL || vs_audio_capture_start(g_social.mic) < 0)
    {
      /* The session continues without audio rather than failing.  The emotion
       * timeline comes from the camera, and a conversation with expressions
       * and no advice is a degraded session; refusing to start would make it
       * no session at all.
       */

      printf("%s: microphone unavailable, continuing without audio\n",
             SOCIAL_TAG);
      vs_audio_capture_close(g_social.mic);
      g_social.mic = NULL;
    }

  if (social_spawn(&g_social.upload_thread, social_upload_worker,
                   "upload") == 0)
    {
      g_social.upload_joinable = true;
    }
  else
    {
      social_post(VS_APP_EVENT_SOCIAL_START_FAILED, -EAGAIN, VS_EMOTION_NONE,
                  0, "系统资源不足");
      goto release;
    }

  if (social_spawn(&g_social.capture_thread, social_capture_worker,
                   "capture") == 0)
    {
      g_social.capture_joinable = true;
    }

  if (g_social.mic != NULL &&
      social_spawn(&g_social.audio_thread, social_audio_worker,
                   "audio") == 0)
    {
      g_social.audio_joinable = true;
    }

  if (!g_social.capture_joinable)
    {
      /* No camera thread means no emotion results at all, which is the whole
       * feature.  Unwind rather than run an empty session.
       */

      pthread_mutex_lock(&g_social.lock);
      g_social.stop_capture = true;
      pthread_cond_broadcast(&g_social.cond);
      pthread_mutex_unlock(&g_social.lock);
      social_post(VS_APP_EVENT_SOCIAL_START_FAILED, -EAGAIN, VS_EMOTION_NONE,
                  0, "系统资源不足");
      goto stop;
    }

  /* Only now is the session actually sampling.  See vs_social.h for why the
   * event waits until here.
   */

  social_post(VS_APP_EVENT_SOCIAL_STARTED, 0, VS_EMOTION_NONE, 0, NULL);

  for (; ; )
    {
      pthread_mutex_lock(&g_social.lock);
      finalize = g_social.finalize;
      aborting = g_social.abort;
      pthread_mutex_unlock(&g_social.lock);

      if (finalize || aborting)
        {
          break;
        }

      social_poll_once();
      usleep(CONFIG_VS_SOCIAL_POLL_INTERVAL_MS * 1000);
    }

  if (aborting)
    {
      goto stop;
    }

  /* finalize_sequence() first, then the totals.  It joins the producers on the
   * way in, which matters twice: the tail audio chunk is counted, and the
   * counters are read after the only threads that write them have stopped
   * rather than while they are still incrementing.
   *
   * The camera is still open at this point -- finalize_sequence() does not
   * release devices -- which is what lets the frame statistics be read.
   */

  social_finalize_sequence();
  social_log_totals();
  social_release_devices();
  goto done;

stop:
  social_stop_producers();
  social_log_totals();

release:
  social_queue_flush();
  social_release_devices();

close_session:
  /* Close the cloud session even when abandoning it.  One deviceId may hold
   * one live session, so walking away would make the next attempt fail with
   * -EBUSY and report a problem unrelated to what actually happened.
   */

  {
    char abandon[VS_CLOUD_MSG_ID_MAX];

    if (vs_cloud_social_finalize(g_social.session.session_id, abandon,
                                 sizeof(abandon)) < 0)
      {
        printf("%s: could not close abandoned session %s\n", SOCIAL_TAG,
               g_social.session.session_id);
      }
  }

done:
  social_queue_flush();
  social_release_devices();

  pthread_mutex_lock(&g_social.lock);
  g_social.running = false;
  pthread_cond_broadcast(&g_social.cond);
  pthread_mutex_unlock(&g_social.lock);
  return NULL;
}"}

{"content":"int vs_social_start(uint32_t request_id)
{
  int ret;

  pthread_mutex_lock(&g_social.lock);

  if (g_social.running)
    {
      pthread_mutex_unlock(&g_social.lock);
      return -EBUSY;
    }

  if (!vs_cloud_configured())
    {
      pthread_mutex_unlock(&g_social.lock);
      printf("%s: no cloud endpoint, refusing to start\n", SOCIAL_TAG);
      return -ENODATA;
    }

  /* A previous session's thread may still be unwinding after posting its
   * terminal event.  Join it here rather than detaching, so the state below is
   * reset with nothing else looking at it.
   */

  if (g_social.session_joinable)
    {
      pthread_t previous = g_social.session_thread;

      g_social.session_joinable = false;
      pthread_mutex_unlock(&g_social.lock);
      pthread_join(previous, NULL);
      pthread_mutex_lock(&g_social.lock);
    }

  /* Everything except the mutex and the condition variable. */

  g_social.paused         = false;
  g_social.stop_capture   = false;
  g_social.producers_done = false;
  g_social.finalize       = false;
  g_social.abort          = false;
  g_social.request_id     = request_id;
  g_social.read           = 0;
  g_social.write          = 0;
  g_social.count          = 0;
  g_social.image_seq      = 0;
  g_social.audio_seq      = 0;
  g_social.dropped        = 0;
  g_social.uploaded       = 0;
  g_social.upload_failed  = 0;
  g_social.inflight_count = 0;
  g_social.inflight_retired = 0;
  g_social.alert_gen      = 1;
  g_social.extreme_streak = 0;
  g_social.calm_streak    = 0;
  g_social.alert_active   = false;
  g_social.alert_since_ms = 0;
  g_social.camera         = NULL;
  g_social.mic            = NULL;
  memset(g_social.slot, 0, sizeof(g_social.slot));
  memset(g_social.inflight, 0, sizeof(g_social.inflight));

  g_social.running = true;
  pthread_mutex_unlock(&g_social.lock);

  ret = social_spawn(&g_social.session_thread, social_session_worker,
                     "session");
  if (ret < 0)
    {
      pthread_mutex_lock(&g_social.lock);
      g_social.running = false;
      pthread_mutex_unlock(&g_social.lock);
      return -EAGAIN;
    }

  g_social.session_joinable = true;
  return 0;
}

int vs_social_pause(void)
{
  pthread_mutex_lock(&g_social.lock);

  if (!g_social.running || g_social.paused || g_social.finalize)
    {
      pthread_mutex_unlock(&g_social.lock);
      return -EINVAL;
    }

  g_social.paused = true;
  pthread_cond_broadcast(&g_social.cond);
  pthread_mutex_unlock(&g_social.lock);

  printf("%s: paused\n", SOCIAL_TAG);
  social_post(VS_APP_EVENT_SOCIAL_PAUSED, 0, VS_EMOTION_NONE, 0, NULL);
  return 0;
}

int vs_social_resume(void)
{
  pthread_mutex_lock(&g_social.lock);

  if (!g_social.running || !g_social.paused || g_social.finalize)
    {
      pthread_mutex_unlock(&g_social.lock);
      return -EINVAL;
    }

  g_social.paused = false;
  pthread_cond_broadcast(&g_social.cond);
  pthread_mutex_unlock(&g_social.lock);

  printf("%s: resumed\n", SOCIAL_TAG);
  social_post(VS_APP_EVENT_SOCIAL_RESUMED, 0, VS_EMOTION_NONE, 0, NULL);
  return 0;
}

int vs_social_finalize(uint32_t request_id)
{
  pthread_mutex_lock(&g_social.lock);"}

{"content":"/****************************************************************************
 * BK7258 Armino-compatible HW_CTRL power-up and heartbeat service.
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <syslog.h>

#include <nuttx/clock.h>
#include <nuttx/kthread.h>
#include <nuttx/mutex.h>
#include <nuttx/signal.h>

#include "hardware/bk7258_mbox.h"
#define IPC_CPU1_POWER_UP_INDICATION   1u
#define IPC_CPU1_HEART_BEAT_INDICATION 2u
#define IPC_ACK_STATE_COMPLETE         2u
#define IPC_RESPONSE_TIMEOUT_MS        600u
#define IPC_HEARTBEAT_INTERVAL         MSEC2TICK(2000)
#define IPC_HEARTBEAT_RETRY            MSEC2TICK(100)
#define IPC_HEARTBEAT_POLL_US           10000u
#define IPC_HEARTBEAT_PRIORITY          110

static mutex_t g_ipc_lock = NXMUTEX_INITIALIZER;
static volatile int g_ipc_ack_result;
static volatile int g_ipc_start_result;
static volatile int g_heartbeat_result;
static volatile bool g_heartbeat_enabled;
static volatile bool g_heartbeat_pending;
static volatile uint32_t g_heartbeat_completions;
static clock_t g_next_heartbeat;
static uint32_t g_heartbeat_failures;
static uint32_t g_heartbeat_submissions;
static uint32_t g_heartbeat_reported;
static bool g_ipc_started;

static int ipc_ack_result(const struct bk7258_mb_wire_message *ack,
                          int result)
{
  if (result == OK &&
      (ack == NULL || ack->reserved != IPC_ACK_STATE_COMPLETE))
    {
      result = -EREMOTEIO;
    }

  return result;
}

static void ipc_tx_complete(const struct bk7258_mb_wire_message *ack,
                            int result, void *arg)
{
  g_ipc_ack_result = ipc_ack_result(ack, result);
  if ((uintptr_t)arg == IPC_CPU1_POWER_UP_INDICATION &&
      g_ipc_ack_result == OK)
    {
      g_heartbeat_result = OK;
      g_next_heartbeat = clock_systime_ticks() + IPC_HEARTBEAT_INTERVAL;
      g_heartbeat_enabled = true;
    }
}

static void ipc_heartbeat_complete(
  const struct bk7258_mb_wire_message *ack, int result, void *arg)
{
  (void)arg;
  g_heartbeat_result = ipc_ack_result(ack, result);
  g_heartbeat_completions++;
  g_heartbeat_pending = false;
}

static int ipc_send(uint8_t command, uint32_t parameter)
{
  struct bk7258_mb_wire_message message;
  volatile uint32_t *payload =
    (volatile uint32_t *)(uintptr_t)BK7258_IPC_TX_ADDRESS;
  int ret;

  ret = nxmutex_lock(&g_ipc_lock);
  if (ret < 0)
    {
      return ret;
    }

  *payload = parameter;
  __asm__ volatile("dmb sy" ::: "memory");

  memset(&message, 0, sizeof(message));
  message.header = command;
  message.payload_address = BK7258_IPC_TX_ADDRESS;
  message.payload_length =
    command == IPC_CPU1_HEART_BEAT_INDICATION ? sizeof(*payload) : 0;
  g_ipc_ack_result = -EINPROGRESS;

  ret = bk7258_mailbox_send_wire(BK7258_MB_CHAN_HW_CTRL_TX, &message,
                                  ipc_tx_complete,
                                  (void *)(uintptr_t)command);
  if (ret == OK)
    {
      ret = bk7258_mailbox_wait_hw_control(IPC_RESPONSE_TIMEOUT_MS);
      if (ret == OK)
        {
          ret = g_ipc_ack_result;
        }
    }

  nxmutex_unlock(&g_ipc_lock);
  return ret > 0 ? -EIO : ret;
}

static int ipc_heartbeat_worker(int argc, char **argv)
{
  (void)argc;
  (void)argv;

  for (;;)
    {
      nxsig_usleep(IPC_HEARTBEAT_POLL_US);
      bk7258_ipc_heartbeat_poll();
    }

  return OK;
}

void bk7258_ipc_heartbeat_poll(void)
{
  struct bk7258_mb_wire_message message;
  volatile uint32_t *payload =
    (volatile uint32_t *)(uintptr_t)BK7258_IPC_TX_ADDRESS;
  clock_t now;
  int ret;

  if (!g_heartbeat_enabled || g_heartbeat_pending)
    {
      return;
    }

  if (g_heartbeat_completions != g_heartbeat_reported)
    {
      g_heartbeat_reported = g_heartbeat_completions;

      /* Only the first ACK is worth a line: it is the evidence that the
       * HW_CTRL round trip works at all.  The next ones say nothing new and
       * they used to print straight into the freshly-drawn NSH prompt
       * ("nsh> IPC: heartbeat queued count=1 ...") for the first six seconds
       * of every boot, which reads like a broken console.  A heartbeat that
       * stops being ACKed is not silent: the failure path below reports it
       * through syslog(LOG_ERR), and the consequence is loud anyway -- the
       * CP resets the part after CONFIG_INT_WDT_PERIOD_MS.
       */

      if (g_heartbeat_reported == 1u)
        {
          printf("IPC: heartbeat ACK result=%d, interval=%u ms\n",
                 g_heartbeat_result,
                 (unsigned int)TICK2MSEC(IPC_HEARTBEAT_INTERVAL));
        }
    }

  if (g_heartbeat_result < 0)
    {
      g_heartbeat_failures++;
      if ((g_heartbeat_failures & (g_heartbeat_failures - 1u)) == 0)
        {
          syslog(LOG_ERR, "IPC heartbeat failed: %d count=%lu\n",
                 g_heartbeat_result,
                 (unsigned long)g_heartbeat_failures);
        }

      g_heartbeat_result = OK;
    }

  now = clock_systime_ticks();
  if ((sclock_t)(now - g_next_heartbeat) < 0)
    {
      return;
    }

  *payload = 0;
  __asm__ volatile("dmb sy" ::: "memory");
  memset(&message, 0, sizeof(message));
  message.header = IPC_CPU1_HEART_BEAT_INDICATION;
  message.payload_address = BK7258_IPC_TX_ADDRESS;
  message.payload_length = sizeof(*payload);
  g_heartbeat_result = -EINPROGRESS;
  g_heartbeat_pending = true;
  ret = bk7258_mailbox_send_wire(BK7258_MB_CHAN_HW_CTRL_TX, &message,
                                 ipc_heartbeat_complete, NULL);
  if (ret == OK)
    {
      g_heartbeat_submissions++;
      g_next_heartbeat = now + IPC_HEARTBEAT_INTERVAL;
    }
  else
    {
      g_heartbeat_pending = false;
      g_heartbeat_result = ret;
      g_next_heartbeat = now + IPC_HEARTBEAT_RETRY;
    }
}

int bk7258_ipc_heartbeat_start(void)
{
  int pid;
  int ret;

  if (g_ipc_started)
    {
      return g_ipc_start_result;
    }

  g_ipc_start_result = -EINPROGRESS;
  g_heartbeat_enabled = false;
  g_heartbeat_pending = false;
  g_heartbeat_completions = 0;
  g_heartbeat_failures = 0;
  g_heartbeat_submissions = 0;
  g_heartbeat_reported = 0;
  ret = ipc_send(IPC_CPU1_POWER_UP_INDICATION, 0);
  g_ipc_start_result = ret < 0 ? ret : OK;

  if (g_ipc_start_result == OK)
    {
      pid = kthread_create("ipc-heartbeat", IPC_HEARTBEAT_PRIORITY, 1536,
                           ipc_heartbeat_worker, NULL);
      if (pid < 0)
        {
          g_ipc_start_result = pid;
        }
    }

  g_ipc_started = g_ipc_start_result == OK;

  if (g_ipc_start_result == OK)
    {
      printf("IPC: HW_CTRL power-up acknowledged by CP, heartbeat armed "
             "now=%llu deadline=%llu\n",
             (unsigned long long)clock_systime_ticks(),
             (unsigned long long)g_next_heartbeat);
    }

  return g_ipc_start_result;
}
"}

{"content":"#define MB_CHANNEL_COUNT       7u
#define MB_RX_CHANNEL_COUNT    6u
#define MB_ACK_SLOT_COUNT      8u
#define MB_ACK_HIGH_WATER      3u
#define MB_TIMEOUT             MSEC2TICK(200)
#define MB_WORK_INTERVAL       MSEC2TICK(10)
#define MB_PROBE_MAX_ATTEMPTS  3u
#define MB_RECOVERY_SLOT_COUNT 4u
#define MB_DOWN_RETRY          MSEC2TICK(100)
#define MB_TX_PRIORITY         105

/* The CP's flash operation notification (its flash_notify.c): the header
 * command carries the edge, param1 the request/acknowledge state.  Values
 * come from the IPC_FLASH_OP_* enumerations there and cross cores, so they
 * are fixed by that side.
 */

#define FLASH_OP_START         0u
#define FLASH_OP_END           1u
#define FLASH_OP_STATE_REQ     1u
#define FLASH_OP_STATE_ACK     2u

enum ack_slot_state
{
  ACK_SLOT_FREE = 0,
  ACK_SLOT_QUEUED,
  ACK_SLOT_SENT
};

struct logical_channel
{
  struct bk7258_mb_wire_message pending;
  bk7258_mb_tx_complete_t callback;
  void *arg;
  int result;
  bool queued;
};

struct active_transaction
{
  struct bk7258_mb_wire_message message __attribute__((aligned(32)));
  bk7258_mb_tx_complete_t callback;
  void *arg;
  clock_t started;
  uint32_t order;
  uint8_t channel_index;
  bool busy;
  bool quarantine;
};

struct ack_slot
{
  struct bk7258_mb_wire_message message __attribute__((aligned(32)));
  uint32_t order;
  enum ack_slot_state state;
};

struct recovery_epoch
{
  struct bk7258_mb_wire_message reset __attribute__((aligned(32)));"}

{"content":"static int dispatch_locked(void)
{
  struct recovery_epoch *epoch = current_recovery();
  struct active_transaction *active;
  struct logical_channel *channel;
  unsigned int i;
  int ret;

  /* ACKs always outrank RESET and ordinary commands. */

  for (i = 0; i < MB_ACK_SLOT_COUNT; i++)
    {
      if (g_ack_slots[i].state != ACK_SLOT_QUEUED)
        {
          continue;
        }

      ret = send_slot(&g_ack_slots[i].message, &g_ack_slots[i].order);
      if (ret < 0)
        {
          return ret;
        }

      g_ack_slots[i].state = ACK_SLOT_SENT;
    }

  if (g_reset_pending)
    {
      ret = send_slot(&epoch->reset, &epoch->reset_order);
      if (ret < 0)
        {
          return ret;
        }

      g_reset_pending = false;
      epoch->reset_sent = true;
      set_link_state(BK7258_MB_LINK_PROBING);
    }

  if (g_active.busy || busy_probe() != NULL)
    {
      return OK;
    }

  for (i = 0; i < MB_CHANNEL_COUNT; i++)
    {
      channel = &g_channels[i];
      if (!channel->queued)
        {
          continue;
        }

      if (g_link_state == BK7258_MB_LINK_PROBING)
        {
          if (g_channel_ids[i] == BK7258_MB_CHAN_UART0_TX &&
              bk7258_mb_header_cmd(&channel->pending) ==
              BK7258_MB_UART_STATE)
            {
              active = &epoch->probe;
            }
          else
            {
              continue;
            }

          if (active == &epoch->probe && active->quarantine &&
              !epoch->replay)
            {
              return -ENOLINK;
            }
        }
      else if (g_link_state == BK7258_MB_LINK_READY)
        {
          active = &g_active;
          if (active->quarantine)
            {
              return -ENOLINK;
            }
        }
      else
        {
          return OK;
        }

      if (!epoch->replay || active != &epoch->probe)
        {
          memset(&active->message, 0, sizeof(active->message));
          memcpy(&active->message, &channel->pending,
                 sizeof(active->message));
          active->message.header = bk7258_mb_make_header(
            bk7258_mb_header_cmd(&channel->pending),
            bk7258_mb_header_state(&channel->pending), 0, ++g_tx_seq,
            g_channel_ids[i]);
        }

      active->callback = channel->callback;
      active->arg = channel->arg;
      active->channel_index = i;
      active->started = clock_systime_ticks();
      active->busy = true;
      ret = send_slot(&active->message, &active->order);
      if (ret < 0)
        {
          active->busy = false;
          return ret;
        }

      if (active == &epoch->probe)
        {
          if (epoch->first_probe_order == 0)
            {
              epoch->first_probe_order = active->order;
            }

          g_probe_attempts++;
          g_stats.probes++;
        }

      return OK;
    }

  return OK;
}

