              break;
            }
        }

      if (ret < 0)
        {
          up_irq_restore(flags);
          return;
        }

      g_uart.tx_read = (g_uart.tx_read + length) % MB_UART_TX_SIZE;
      g_uart.stats.data_tx++;
      up_irq_restore(flags);

      /* Give the CP time to copy the payload out before the next chunk
       * overwrites it.  Its receive handler takes microseconds, so this is
       * slack rather than a measured requirement -- and at this size a whole
       * dump spends well under a millisecond here in total.
       */

      for (spin = 0; spin < MB_UART_POLLED_SETTLE_SPINS; spin++)
        {
          __asm__ volatile("nop");
        }
    }
}

