/****************************************************************************
 * Name: social_wav_le16 / social_wav_le32
 *
 * Description:
 *   Read a little-endian field out of a RIFF header without assuming the
 *   host's byte order or that the field is aligned.  Both hold on this chip,
 *   and neither is worth depending on for eight lines of code.
 *
 ****************************************************************************/

static uint16_t social_wav_le16(const unsigned char *p)
{
  return (uint16_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
}

static uint32_t social_wav_le32(const unsigned char *p)
{
  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
         ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

/****************************************************************************
 * Name: social_play_minutes_audio
 *
 * Description:
 *   Fetch ttsMinutes and speak it.
 *
 *   This is the step the interface document describes and the firmware never
 *   took: vs_cloud_download() existed with no caller, so tts_url was logged
 *   and dropped.  The AI端 confirmed it is the only way to get the voice --
 *   "你要语音是必须要走url下载的" -- and it is a separate file from the text,
 *   not a spoken copy of it.
 *
 *   Everything here is best effort and reported rather than propagated.  By
 *   the time this runs the summary is on screen and the record is on disk;
 *   failing the session because the speaker could not be fed would throw away
 *   the part the user actually asked for.
 *
 *   Format is read from the bytes, not from Content-Type -- FDS answers
 *   application/octet-stream for everything.  Measured 2026-09-04: RIFF/WAVE,
 *   PCM, 24 kHz, 16-bit, mono, 48000 bytes per second.
 *
 ****************************************************************************/

static void social_play_minutes_audio(const char *url)
{
  struct vs_audio_pb_s *pb = NULL;
  unsigned char *wav = NULL;
  bool wav_psram = false;
  size_t len = 0;
  size_t pos = 12;
  size_t data_off = 0;
  size_t data_len = 0;
  unsigned int rate = 0;
  unsigned int channels = 0;
  unsigned int bits = 0;
  bool have_fmt = false;
  int ret;

  if (url == NULL || url[0] == '\0')
    {
      return;
    }

  ret = vs_cloud_download(url, &wav, &len, &wav_psram,
                          CONFIG_VS_SOCIAL_DOWNLOAD_MAX_BYTES);
  if (ret < 0)
    {
      /* -EFBIG is the interesting one: it means the spoken minutes outgrew
       * CONFIG_VS_SOCIAL_DOWNLOAD_MAX_BYTES, which is a number to raise
       * rather than a fault to chase.  Say so specifically.
       */

      printf("%s: spoken minutes not fetched: %d%s\n", SOCIAL_TAG, ret,
             ret == -EFBIG ? " (raise VS_SOCIAL_DOWNLOAD_MAX_BYTES)" : "");
      return;
    }

  /* Walk the chunk list rather than assuming the canonical 44-byte header.
   * A writer is free to put LIST or fact ahead of data, and one that does
   * would otherwise have its metadata played as audio.
   */

  if (len < 44 || memcmp(wav, "RIFF", 4) != 0 ||
      memcmp(wav + 8, "WAVE", 4) != 0)
    {
      printf("%s: spoken minutes are not RIFF/WAVE, %zu bytes\n", SOCIAL_TAG,
             len);
      goto out;
    }

  while (pos + 8 <= len)
    {
      const unsigned char *id = wav + pos;
      uint32_t size = social_wav_le32(wav + pos + 4);
      size_t body = pos + 8;

      if (memcmp(id, "fmt ", 4) == 0 && size >= 16 && body + 16 <= len)
        {
          if (social_wav_le16(wav + body) != 1)
            {
              printf("%s: spoken minutes are compressed, format %u\n",
                     SOCIAL_TAG, social_wav_le16(wav + body));
              goto out;
            }

          channels = social_wav_le16(wav + body + 2);
          rate     = social_wav_le32(wav + body + 4);
          bits     = social_wav_le16(wav + body + 14);
          have_fmt = true;
        }
      else if (memcmp(id, "data", 4) == 0)
        {
          data_off = body;

          /* Trust the shorter of the declared length and what arrived.  A
           * truncated download would otherwise walk off the buffer, and
           * vs_cloud_download() only guarantees Content-Length was reached,
           * not that the writer's size field agreed with it.
           */

          data_len = size;
          if (data_off + data_len > len)
            {
              data_len = len - data_off;
            }

          break;
        }

      pos = body + size + (size & 1u); /* chunks are word aligned */
    }

  if (!have_fmt || data_len == 0)
    {
      printf("%s: spoken minutes have no playable data chunk\n", SOCIAL_TAG);
      goto out;
    }

  if (bits != 16)
    {
      printf("%s: spoken minutes are %u-bit, only 16 is supported\n",
             SOCIAL_TAG, bits);
      goto out;
    }

  printf("%s: spoken minutes %zu bytes, %u Hz %u ch %u-bit, %.1f s\n",
         SOCIAL_TAG, data_len, rate, channels, bits,
         rate * channels > 0 ?
           (double)data_len / (double)(rate * channels * 2u) : 0.0);

  pb = vs_audio_playback_open(AGENT_AUDIO_PLAYBACK_DEV, rate, channels, bits);
  if (pb == NULL)
    {
      printf("%s: spoken minutes: playback open failed\n", SOCIAL_TAG);
      goto out;
    }

  /* Chunked rather than one write, so an abandon while speaking is acted on
   * within a chunk instead of after the whole file.  The ring absorbs these
   * without pacing, so the size only bounds the reaction time.
   */

  for (pos = 0; pos < data_len; )
    {
      size_t chunk = data_len - pos;
      bool aborting;

      if (chunk > 8192)
        {
          chunk = 8192;
        }

      pthread_mutex_lock(&g_social.lock);
      aborting = g_social.abort;
      pthread_mutex_unlock(&g_social.lock);

      if (aborting)
        {
          vs_audio_playback_stop(pb);
          break;
        }

      ret = vs_audio_playback_write(pb, wav + data_off + pos, chunk);
      if (ret < 0)
        {
          if (ret != -ECANCELED)
            {
              printf("%s: spoken minutes write failed: %d\n", SOCIAL_TAG,
                     ret);
            }

          break;
        }

      pos += chunk;
    }

  vs_audio_playback_drain(pb);

  if (vs_audio_playback_underruns(pb) > 0)
    {
      printf("%s: spoken minutes underran %u times\n", SOCIAL_TAG,
             vs_audio_playback_underruns(pb));
    }

  vs_audio_playback_close(pb);

out:
  vs_cloud_release(wav, wav_psram);
}

