                return VELA_TLS_ERR_PROTOCOL;
            break;

        case CHK_DATA: {
            size_t n = len - pos;

            if (n > d->remain)
                n = (size_t)d->remain;

            if (sink(sink_arg, data + pos, n) < 0)
                return VELA_TLS_ERR_SINK;

            if (delivered)
                *delivered += n;

            pos += n;
            d->remain -= n;

            if (d->remain == 0)
                d->state = CHK_DATA_CR;
            break;
        }

        case CHK_DATA_CR:
            if (c == '\r') {
                d->state = CHK_DATA_LF;
                pos++;
            } else if (c == '\n') {
                d->state = CHK_SIZE;
                d->remain = 0;
                pos++;
            } else {
                return VELA_TLS_ERR_PROTOCOL;
            }
            break;

        case CHK_DATA_LF:
            if (c == '\n')
                pos++;
            d->state = CHK_SIZE;
            d->remain = 0;
            break;

        default:
            pos++;
            break;
        }
    }

    return 0;
}

