/* Host-side test of the incremental chunked decoder added to vela_tls.c.
 *
 * The functions below are copied verbatim from
 * packages/ai_agent/src/infra/vela_tls.c.  The point of the exercise is the
 * property the streaming TTS download depends on: PCM audio is full of 0x0D
 * and 0x0A bytes, so the decoder must never look for a line ending while it is
 * inside chunk data.
 */

#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define VELA_TLS_ERR_SINK     -6
#define VELA_TLS_ERR_PROTOCOL -7

typedef int (*vela_body_sink_t)(void *arg, const void *data, size_t len);

static int failures;

#define CHECK(cond, what)                                              \
  do {                                                                 \
    if (cond) { printf("  ok    %s\n", what); }                        \
    else      { printf("  FAIL  %s\n", what); failures++; }            \
  } while (0)

/* ---- verbatim from vela_tls.c ------------------------------------ */

typedef enum {
    CHK_SIZE,
    CHK_EXT,
    CHK_SIZE_LF,
    CHK_DATA,
    CHK_DATA_CR,
    CHK_DATA_LF,
    CHK_DONE
} chunk_state_t;

typedef struct {
    chunk_state_t state;
    unsigned long remain;
    int digits;
} chunk_dec_t;

static int chunk_hexval(char c)
{
    if (c >= '0' && c <= '9')
        return c - '0';
    if (c >= 'a' && c <= 'f')
        return c - 'a' + 10;
    if (c >= 'A' && c <= 'F')
        return c - 'A' + 10;
    return -1;
}

static int chunk_size_done(chunk_dec_t* d)
{
    if (d->digits == 0)
        return -1;

    d->digits = 0;
    d->state = d->remain == 0 ? CHK_DONE : CHK_DATA;
    return 0;
}

static int chunk_feed(chunk_dec_t* d, const char* data, size_t len,
    vela_body_sink_t sink, void* sink_arg, size_t* delivered)
{
    size_t pos = 0;

    while (pos < len && d->state != CHK_DONE) {
        char c = data[pos];

        switch (d->state) {
        case CHK_SIZE: {
            int v = chunk_hexval(c);

            if (v >= 0) {
                d->remain = d->remain * 16u + (unsigned long)v;
                d->digits++;
                pos++;
            } else if (c == ';') {
                d->state = CHK_EXT;
                pos++;
            } else if (c == '\r') {
                d->state = CHK_SIZE_LF;
                pos++;
            } else if (c == '\n') {
                pos++;
                if (chunk_size_done(d) < 0)
                    return VELA_TLS_ERR_PROTOCOL;
            } else if (c == ' ' || c == '\t') {
                pos++;
            } else {
                return VELA_TLS_ERR_PROTOCOL;
            }
            break;
        }

        case CHK_EXT:
            if (c == '\r') {
                d->state = CHK_SIZE_LF;
            } else if (c == '\n') {
                pos++;
                if (chunk_size_done(d) < 0)
                    return VELA_TLS_ERR_PROTOCOL;
                break;
            }
            pos++;
            break;

        case CHK_SIZE_LF:
            if (c == '\n')
                pos++;
            if (chunk_size_done(d) < 0)
                return VELA_TLS_ERR_PROTOCOL;
            break;

        case CHK_DATA: {
            size_t n = len - pos;

            if (n > d->remain)
                n = (size_t)d->remain;

            if (sink(sink_arg, data + pos, n) < 0)
                return VELA_TLS_ERR_SINK;

            if (delivered)
                *delivered += n;

            pos += n;
            d->remain -= n;

            if (d->remain == 0)
                d->state = CHK_DATA_CR;
            break;
        }

        case CHK_DATA_CR:
            if (c == '\r') {
                d->state = CHK_DATA_LF;
                pos++;
            } else if (c == '\n') {
                d->state = CHK_SIZE;
                d->remain = 0;
                pos++;
            } else {
                return VELA_TLS_ERR_PROTOCOL;
            }
            break;

        case CHK_DATA_LF:
            if (c == '\n')
                pos++;
            d->state = CHK_SIZE;
            d->remain = 0;
            break;

        default:
            pos++;
            break;
        }
    }

    return 0;
}

/* ---- harness ----------------------------------------------------- */

struct acc
{
  unsigned char buf[65536];
  size_t len;
  int fail_after;   /* refuse once this many bytes have been taken, -1 never */
};

static int acc_sink(void *arg, const void *data, size_t len)
{
  struct acc *a = arg;

  if (a->fail_after >= 0 && a->len + len > (size_t)a->fail_after)
    {
      return -1;
    }

  if (a->len + len > sizeof(a->buf))
    {
      return -1;
    }

  memcpy(a->buf + a->len, data, len);
  a->len += len;
  return 0;
}

/* Feed the whole encoding in slices of exactly step bytes (0 means one shot). */

static int run(const char *enc, size_t enc_len, size_t step,
               struct acc *out, int fail_after)
{
  chunk_dec_t d = { CHK_SIZE, 0, 0 };
  size_t delivered = 0;
  size_t pos = 0;
  int ret = 0;

  memset(out, 0, sizeof(*out));
  out->fail_after = fail_after;

  if (step == 0)
    {
      step = enc_len > 0 ? enc_len : 1;
    }

  while (pos < enc_len)
    {
      size_t n = enc_len - pos;

      if (n > step)
        {
          n = step;
        }

      ret = chunk_feed(&d, enc + pos, n, acc_sink, out, &delivered);
      if (ret != 0)
        {
          return ret;
        }

      pos += n;

      if (d.state == CHK_DONE)
        {
          break;
        }
    }

  if (delivered != out->len)
    {
      printf("  FAIL  delivered counter %zu != sink bytes %zu\n", delivered,
             out->len);
      failures++;
    }

  return 0;
}

/* Same input at every slicing from 1 byte up to the whole thing must give
 * byte-identical output.  This is the property that matters: the transport
 * hands over whatever TCP happened to deliver.
 */

static void expect_all_slicings(const char *enc, size_t enc_len,
                                const unsigned char *want, size_t want_len,
                                const char *what)
{
  size_t step;

  for (step = 1; step <= enc_len; step++)
    {
      struct acc got;

      if (run(enc, enc_len, step, &got, -1) != 0)
        {
          printf("  FAIL  %s: error at step %zu\n", what, step);
          failures++;
          return;
        }

      if (got.len != want_len || memcmp(got.buf, want, want_len) != 0)
        {
          printf("  FAIL  %s: mismatch at step %zu (%zu vs %zu bytes)\n", what,
                 step, got.len, want_len);
          failures++;
          return;
        }
    }

  printf("  ok    %s (all %zu slicings)\n", what, enc_len);
}

int main(void)
{
  puts("framing");
  {
    const char enc[] = "4\r\nWave\r\n5\r\nform!\r\n0\r\n\r\n";

    expect_all_slicings(enc, sizeof(enc) - 1,
                        (const unsigned char *)"Waveform!", 9,
                        "two chunks then terminator");
  }

  {
    const char enc[] = "1a\r\nabcdefghijklmnopqrstuvwxyz\r\n0\r\n\r\n";

    expect_all_slicings(enc, sizeof(enc) - 1,
                        (const unsigned char *)"abcdefghijklmnopqrstuvwxyz",
                        26, "multi-digit hex size");
  }

  {
    const char enc[] = "1A\r\nabcdefghijklmnopqrstuvwxyz\r\n0\r\n\r\n";

    expect_all_slicings(enc, sizeof(enc) - 1,
                        (const unsigned char *)"abcdefghijklmnopqrstuvwxyz",
                        26, "uppercase hex size");
  }

  {
    const char enc[] = "4;name=value\r\nWave\r\n0\r\n\r\n";

    expect_all_slicings(enc, sizeof(enc) - 1,
                        (const unsigned char *)"Wave", 4,
                        "chunk-extension discarded");
  }

  {
    const char enc[] = "4\nWave\n0\n\n";

    expect_all_slicings(enc, sizeof(enc) - 1,
                        (const unsigned char *)"Wave", 4,
                        "bare LF line endings");
  }

  {
    const char enc[] = "4 \r\nWave\r\n0\r\n\r\n";

    expect_all_slicings(enc, sizeof(enc) - 1,
                        (const unsigned char *)"Wave", 4,
                        "trailing space after the size");
  }

  puts("\nbinary payload (the reason this exists)");
  {
    /* Every byte value, including CR, LF and the CRLF pair, inside one chunk.
     * A decoder that scanned for a line ending while in data would cut this
     * short -- which on a WAV means audio that stops after a fraction of a
     * second.
     */

    unsigned char want[256];
    char enc[1024];
    size_t i;
    int n;

    for (i = 0; i < 256; i++)
      {
        want[i] = (unsigned char)i;
      }

    n = snprintf(enc, sizeof(enc), "100\r\n");
    memcpy(enc + n, want, 256);
    memcpy(enc + n + 256, "\r\n0\r\n\r\n", 7);

    expect_all_slicings(enc, (size_t)n + 256 + 7, want, 256,
                        "all 256 byte values pass through unchanged");
  }

  {
    /* A chunk boundary landing immediately after a CR in the payload: the
     * decoder must take the CR as data and the next CRLF as framing.
     */

    const char enc[] = "3\r\na\rb\r\n3\r\nc\nd\r\n0\r\n\r\n";
    const unsigned char want[] = { 'a', '\r', 'b', 'c', '\n', 'd' };

    expect_all_slicings(enc, sizeof(enc) - 1, want, sizeof(want),
                        "payload ending in CR is not confused with framing");
  }

  {
    /* PCM-shaped: a 24 kHz 16-bit sample run that contains 0x0d0a pairs. */

    unsigned char want[600];
    char enc[2048];
    size_t i;
    int n;

    for (i = 0; i < sizeof(want); i += 2)
      {
        want[i]     = 0x0d;
        want[i + 1] = 0x0a;
      }

    n = snprintf(enc, sizeof(enc), "%zx\r\n", sizeof(want));
    memcpy(enc + n, want, sizeof(want));
    memcpy(enc + n + sizeof(want), "\r\n0\r\n\r\n", 7);

    expect_all_slicings(enc, (size_t)n + sizeof(want) + 7, want, sizeof(want),
                        "a chunk of nothing but CRLF pairs survives intact");
  }

  puts("\ntermination and errors");
  {
    const char enc[] = "4\r\nWave\r\n0\r\n\r\n4\r\nMORE\r\n";
    struct acc got;

    CHECK(run(enc, sizeof(enc) - 1, 1, &got, -1) == 0 &&
          got.len == 4 && memcmp(got.buf, "Wave", 4) == 0,
          "nothing after the zero chunk is delivered");
  }

  {
    /* A trailer after the terminator is ignored rather than parsed.  This is
     * why the streaming path refuses to pool such a connection.
     */

    const char enc[] = "4\r\nWave\r\n0\r\nExpires: soon\r\n\r\n";
    struct acc got;

    CHECK(run(enc, sizeof(enc) - 1, 1, &got, -1) == 0 && got.len == 4,
          "a trailer is ignored, not delivered");
  }

  {
    const char enc[] = "\r\nWave\r\n";
    struct acc got;

    CHECK(run(enc, sizeof(enc) - 1, 0, &got, -1) == VELA_TLS_ERR_PROTOCOL,
          "a size line with no digits is a framing error, not a terminator");
  }

  {
    const char enc[] = "4\r\nWaveXX";
    struct acc got;

    CHECK(run(enc, sizeof(enc) - 1, 0, &got, -1) == VELA_TLS_ERR_PROTOCOL,
          "garbage where the post-data CRLF belongs is rejected");
  }

  {
    const char enc[] = "zz\r\nWave\r\n";
    struct acc got;

    CHECK(run(enc, sizeof(enc) - 1, 0, &got, -1) == VELA_TLS_ERR_PROTOCOL,
          "a non-hex size is rejected");
  }

  {
    const char enc[] = "8\r\nWaveform\r\n0\r\n\r\n";
    struct acc got;

    CHECK(run(enc, sizeof(enc) - 1, 0, &got, 4) == VELA_TLS_ERR_SINK,
          "a sink that refuses is reported as VELA_TLS_ERR_SINK");
  }

  {
    /* Truncated mid-data: no error, just fewer bytes.  The transport reports
     * this through the Content-Length or EOF path, and vs_cloud checks the
     * length it got, so the decoder does not need to invent a failure.
     */

    const char enc[] = "8\r\nWave";
    struct acc got;

    CHECK(run(enc, sizeof(enc) - 1, 0, &got, -1) == 0 && got.len == 4,
          "a body cut off mid-chunk delivers what arrived");
  }

  {
    const char enc[] = "0\r\n\r\n";
    struct acc got;

    CHECK(run(enc, sizeof(enc) - 1, 0, &got, -1) == 0 && got.len == 0,
          "an empty body is not an error");
  }

  printf("\n%s (%d failure%s)\n", failures == 0 ? "PASS" : "FAIL", failures,
         failures == 1 ? "" : "s");
  return failures != 0;
