if (!have_fmt || data_len == 0)
  {
    printf("%s: spoken minutes have no playable data chunk\n", SOCIAL_TAG);
    goto out;
  }

if (bits != 16)
  {
    printf("%s: spoken minutes are %u-bit, only 16 is supported\n",
           SOCIAL_TAG, bits);
