/* Host-side test of the file-based RIFF walker added to vs_social.c.
 *
 * social_read_exact() and social_wav_open() below are copied verbatim.  Real
 * files are written to /tmp and opened through the real syscalls, because the
 * thing being checked is the arithmetic that decides where the first PCM
 * sample is: a walker that is one byte off does not fail, it plays noise.
 */

#include <errno.h>
#include <fcntl.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#define SOCIAL_TAG "social"

static int failures;

#define CHECK(cond, what)                                              \
  do {                                                                 \
    if (cond) { printf("  ok    %s\n", what); }                        \
    else      { printf("  FAIL  %s\n", what); failures++; }            \
  } while (0)

/* ---- verbatim from vs_social.c ------------------------------------ */

static uint16_t social_wav_le16(const unsigned char *p)
{
  return (uint16_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
}

static uint32_t social_wav_le32(const unsigned char *p)
{
  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
         ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static int social_read_exact(int fd, void *buf, size_t len)
{
  unsigned char *p = buf;
  size_t off = 0;

  while (off < len)
    {
      ssize_t n = read(fd, p + off, len - off);

      if (n < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          return -errno;
        }

      if (n == 0)
        {
          return -ENODATA;
        }

      off += (size_t)n;
    }

  return 0;
}

static int social_wav_open(const char *path, size_t file_len, int *fd_out,
                          unsigned int *rate, unsigned int *channels,
                          unsigned int *bits, size_t *data_len)
{
  unsigned char head[16];
  bool have_fmt = false;
  size_t pos;
  int guard;
  int fd;
  int ret;

  *rate = *channels = *bits = 0;
  *data_len = 0;

  fd = open(path, O_RDONLY);
  if (fd < 0)
    {
      return -errno;
    }

  ret = social_read_exact(fd, head, 12);
  if (ret < 0)
    {
      goto err;
    }

  if (memcmp(head, "RIFF", 4) != 0 || memcmp(head + 8, "WAVE", 4) != 0)
    {
      printf("%s: spoken minutes are not RIFF/WAVE\n", SOCIAL_TAG);
      ret = -EINVAL;
      goto err;
    }

  pos = 12;

  for (guard = 0; guard < 64; guard++)
    {
      uint32_t size;
      size_t skip;

      ret = social_read_exact(fd, head, 8);
      if (ret < 0)
        {
          ret = -EINVAL;
          goto err;
        }

      size = social_wav_le32(head + 4);
      pos += 8;
      skip = (size_t)size + (size & 1u);

      if (memcmp(head, "data", 4) == 0)
        {
          size_t avail = file_len > pos ? file_len - pos : 0;

          if (!have_fmt)
            {
              printf("%s: spoken minutes have data before fmt\n", SOCIAL_TAG);
              ret = -EINVAL;
              goto err;
            }

          *data_len = (size_t)size < avail ? (size_t)size : avail;
          if (*data_len == 0)
            {
              ret = -ENODATA;
              goto err;
            }

          *fd_out = fd;
          return 0;
        }

      if (memcmp(head, "fmt ", 4) == 0 && size >= 16)
        {
          unsigned char fmt[16];

          ret = social_read_exact(fd, fmt, sizeof(fmt));
          if (ret < 0)
            {
              goto err;
            }

          if (social_wav_le16(fmt) != 1)
            {
              printf("%s: spoken minutes are compressed, format %u\n",
                     SOCIAL_TAG, social_wav_le16(fmt));
              ret = -ENOTSUP;
              goto err;
            }

          *channels = social_wav_le16(fmt + 2);
          *rate     = social_wav_le32(fmt + 4);
          *bits     = social_wav_le16(fmt + 14);
          have_fmt  = true;
          skip -= sizeof(fmt);
        }

      if (skip > 0 && lseek(fd, (off_t)skip, SEEK_CUR) < 0)
        {
          ret = -errno;
          goto err;
        }

      pos += skip;
    }

  ret = -EINVAL;

err:
  close(fd);
  return ret;
}

/* ---- builders ---------------------------------------------------- */

static unsigned char g_file[8192];
static size_t g_len;

static void put(const void *p, size_t n)
{
  memcpy(g_file + g_len, p, n);
  g_len += n;
}

static void put32(uint32_t v)
{
  unsigned char b[4] = { (unsigned char)v, (unsigned char)(v >> 8),
                         (unsigned char)(v >> 16), (unsigned char)(v >> 24) };
  put(b, 4);
}

static void put16(uint16_t v)
{
  unsigned char b[2] = { (unsigned char)v, (unsigned char)(v >> 8) };
  put(b, 2);
}

static void begin(void)
{
  g_len = 0;
  memset(g_file, 0, sizeof(g_file));
  put("RIFF", 4);
  put32(0); /* patched later, and deliberately never trusted by the walker */
  put("WAVE", 4);
}

/* fmt chunk with a declared size that may exceed the 16 bytes of PCM fields,
 * which is what WAVE_FORMAT_EXTENSIBLE writers do.
 */

static void put_fmt(uint16_t tag, uint16_t ch, uint32_t rate, uint16_t bits,
                    uint32_t declared)
{
  size_t extra;

  put("fmt ", 4);
  put32(declared);
  put16(tag);
  put16(ch);
  put32(rate);
  put32(rate * ch * bits / 8);
  put16((uint16_t)(ch * bits / 8));
  put16(bits);

  for (extra = 16; extra < declared; extra++)
    {
      unsigned char pad = 0xcc;
      put(&pad, 1);
    }

  if (declared & 1u)
    {
      unsigned char pad = 0;
      put(&pad, 1);
    }
}

static void put_chunk(const char *id, const unsigned char *body, uint32_t n)
{
  put(id, 4);
  put32(n);
  if (n > 0)
    {
      put(body, n);
    }

  if (n & 1u)
    {
      unsigned char pad = 0;
      put(&pad, 1);
    }
}

static const char *flush(const char *name)
{
  static char path[256];
  int fd;

  snprintf(path, sizeof(path), "/tmp/%s", name);
  fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0600);
  if (fd < 0)
    {
      printf("  FAIL  cannot write %s\n", path);
      failures++;
      return path;
    }

  if (write(fd, g_file, g_len) != (ssize_t)g_len)
    {
      printf("  FAIL  short write to %s\n", path);
      failures++;
    }

  close(fd);
  return path;
}

/* A recognisable payload: no byte is zero, so a mispositioned read shows up. */

static void fill_pcm(unsigned char *p, size_t n, unsigned char seed)
{
  size_t i;

  for (i = 0; i < n; i++)
    {
      p[i] = (unsigned char)(seed + i);
    }
}

int main(void)
{
  unsigned char pcm[512];
  unsigned int rate;
  unsigned int ch;
  unsigned int bits;
  size_t dlen;
  int fd = -1;
  int ret;

  fill_pcm(pcm, sizeof(pcm), 0x41);

  puts("canonical file");
  {
    const char *path;

    begin();
    put_fmt(1, 1, 24000, 16, 16);
    put_chunk("data", pcm, 256);
    path = flush("vs_wav_canon.wav");

    ret = social_wav_open(path, g_len, &fd, &rate, &ch, &bits, &dlen);
    CHECK(ret == 0, "opens");
    CHECK(rate == 24000 && ch == 1 && bits == 16, "24000 Hz mono 16-bit");
    CHECK(dlen == 256, "data length is 256");

    if (ret == 0)
      {
        unsigned char got[256];

        CHECK(lseek(fd, 0, SEEK_CUR) == 44, "positioned at byte 44");
        CHECK(social_read_exact(fd, got, 256) == 0 &&
              memcmp(got, pcm, 256) == 0,
              "the bytes read are the payload, not the header");
        close(fd);
      }
  }

  puts("\nchunks before data");
  {
    const char *path;
    unsigned char junk[4] = { 0xde, 0xad, 0xbe, 0xef };

    begin();
    put_fmt(1, 1, 16000, 16, 16);
    put_chunk("LIST", junk, 4);
    put_chunk("data", pcm, 128);
    path = flush("vs_wav_list.wav");

    ret = social_wav_open(path, g_len, &fd, &rate, &ch, &bits, &dlen);
    CHECK(ret == 0 && rate == 16000 && dlen == 128, "a LIST chunk is skipped");

    if (ret == 0)
      {
        unsigned char got[128];

        CHECK(social_read_exact(fd, got, 128) == 0 &&
              memcmp(got, pcm, 128) == 0,
              "and the payload is still where it should be");
        close(fd);
      }
  }

  {
    const char *path;
    unsigned char junk[3] = { 0xaa, 0xbb, 0xcc };

    begin();
    put_fmt(1, 2, 48000, 16, 16);
    put_chunk("fact", junk, 3); /* odd: needs a pad byte */
    put_chunk("data", pcm, 64);
    path = flush("vs_wav_odd.wav");

    ret = social_wav_open(path, g_len, &fd, &rate, &ch, &bits, &dlen);
    CHECK(ret == 0 && ch == 2 && dlen == 64,
          "an odd-length chunk is skipped with its pad byte");

    if (ret == 0)
      {
        unsigned char got[64];

        CHECK(social_read_exact(fd, got, 64) == 0 &&
              memcmp(got, pcm, 64) == 0,
              "and the pad byte was not played as audio");
        close(fd);
      }
  }

  {
    /* WAVE_FORMAT_EXTENSIBLE: fmt declares 40 bytes, of which only the first
     * 16 are read.  The remaining 24 must be skipped, not played.
     */

    const char *path;

    begin();
    put_fmt(1, 1, 24000, 16, 40);
    put_chunk("data", pcm, 96);
    path = flush("vs_wav_ext.wav");

    ret = social_wav_open(path, g_len, &fd, &rate, &ch, &bits, &dlen);
    CHECK(ret == 0 && rate == 24000 && dlen == 96,
          "a 40-byte fmt chunk is skipped past correctly");

    if (ret == 0)
      {
        unsigned char got[96];

        CHECK(social_read_exact(fd, got, 96) == 0 &&
              memcmp(got, pcm, 96) == 0,
              "and the extension bytes are not played as audio");
        close(fd);
      }
  }

  {
    /* fmt with a declared size below 16 is not a PCM fmt; it must be skipped
     * generically rather than have 16 bytes read out of it.
     */

    const char *path;
    unsigned char tiny[8] = { 1, 0, 1, 0, 0, 0, 0, 0 };

    begin();
    put_chunk("fmt ", tiny, 8);
    put_fmt(1, 1, 8000, 16, 16);
    put_chunk("data", pcm, 32);
    path = flush("vs_wav_tinyfmt.wav");

    ret = social_wav_open(path, g_len, &fd, &rate, &ch, &bits, &dlen);
    CHECK(ret == 0 && rate == 8000 && dlen == 32,
          "an undersized fmt chunk is skipped, the real one is used");

    if (ret == 0)
      {
        close(fd);
      }
  }

  puts("\nclamping and rejection");
  {
    /* data claims more than the file holds -- a truncated download. */

    const char *path;

    begin();
    put_fmt(1, 1, 24000, 16, 16);
    put("data", 4);
    put32(100000); /* declared */
    put(pcm, 200); /* actual */
    path = flush("vs_wav_trunc.wav");

    ret = social_wav_open(path, g_len, &fd, &rate, &ch, &bits, &dlen);
    CHECK(ret == 0 && dlen == 200,
          "a data chunk longer than the file is clamped to what arrived");

    if (ret == 0)
      {
        close(fd);
      }
  }

  {
    const char *path;

    begin();
    put_fmt(0x11, 1, 24000, 4, 20); /* IMA ADPCM */
    put_chunk("data", pcm, 64);
    path = flush("vs_wav_adpcm.wav");

    ret = social_wav_open(path, g_len, &fd, &rate, &ch, &bits, &dlen);
    CHECK(ret == -ENOTSUP, "a compressed file is rejected with -ENOTSUP");
  }

  {
    const char *path;

    begin();
    put_chunk("data", pcm, 64);
    put_fmt(1, 1, 24000, 16, 16);
    path = flush("vs_wav_datafirst.wav");

    ret = social_wav_open(path, g_len, &fd, &rate, &ch, &bits, &dlen);
    CHECK(ret == -EINVAL, "data before fmt is rejected rather than guessed");
  }

  {
    const char *path;

    begin();
    put_fmt(1, 1, 24000, 16, 16);
    path = flush("vs_wav_nodata.wav");

    ret = social_wav_open(path, g_len, &fd, &rate, &ch, &bits, &dlen);
    CHECK(ret == -EINVAL, "a file with no data chunk is rejected");
  }

  {
    const char *path;

    begin();
    put_fmt(1, 1, 24000, 16, 16);
    put_chunk("data", pcm, 0);
    path = flush("vs_wav_emptydata.wav");

    ret = social_wav_open(path, g_len, &fd, &rate, &ch, &bits, &dlen);
    CHECK(ret == -ENODATA, "an empty data chunk is -ENODATA");
  }

  {
    /* An HTML error page saved with a .wav name: the realistic garbage. */

    const char *path;
    int wfd;

    path = "/tmp/vs_wav_html.wav";
    wfd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0600);
    if (wfd >= 0)
      {
        const char *html = "<?xml version=\"1.0\"?><Error><Code>AccessDenied"
                           "</Code></Error>";
        ssize_t w = write(wfd, html, strlen(html));

        (void)w;
        close(wfd);
      }

    ret = social_wav_open(path, 60, &fd, &rate, &ch, &bits, &dlen);
    CHECK(ret == -EINVAL, "an XML error document is rejected, not played");
  }

  {
    const char *path;
    int wfd;

    path = "/tmp/vs_wav_empty.wav";
    wfd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0600);
    if (wfd >= 0)
      {
        close(wfd);
      }

    ret = social_wav_open(path, 0, &fd, &rate, &ch, &bits, &dlen);
    CHECK(ret == -ENODATA, "a zero-length file is -ENODATA, not a crash");
