{"content":"int vs_cloud_download_to_file(const char *url, const char *path,
                              size_t max_bytes, size_t *len)
{
  struct cloud_url_s *parsed = NULL;
  struct cloud_file_sink_s sink;
  char *scratch = NULL;
  bool parsed_psram = false;
  bool scratch_psram = false;
  int http;
  int ret;

  if (url == NULL || url[0] == '\0' || path == NULL || max_bytes == 0)
    {
      return -EINVAL;
    }

  if (len != NULL)
    {
      *len = 0;
    }

  memset(&sink, 0, sizeof(sink));
  sink.fd = -1;
  sink.max_bytes = max_bytes;
  sink.next_report = CLOUD_DOWNLOAD_REPORT_STRIDE;

  parsed = cloud_alloc(sizeof(*parsed), &parsed_psram);
  if (parsed == NULL)
    {
      return -ENOMEM;
    }

  ret = cloud_url_parse(url, parsed);
  if (ret < 0)
    {
      if (ret == -EPROTONOSUPPORT)
        {
          printf("%s: cannot download %s, unsupported scheme\n", CLOUD_TAG,
                 url);
        }

      goto out;
    }

  /* Holds the response header block, and on the cleartext path doubles as the
   * read buffer the sink is fed from.  The TLS path uses its own 8 KB staging
   * buffer and ignores this one.  Either way it is the whole memory cost of
   * the transfer, which is the point of this function.
   */

  scratch = cloud_alloc(CONFIG_VS_SOCIAL_REG_RESP_BYTES, &scratch_psram);
  if (scratch == NULL)
    {
      ret = -ENOMEM;
      goto out;
    }

  sink.fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0600);
  if (sink.fd < 0)
    {
      ret = -errno;
      printf("%s: cannot create %s: %d\n", CLOUD_TAG, path, ret);
      goto out;
    }

  http = cloud_http_ex(parsed, "GET", NULL, NULL, 0, scratch,
                       CONFIG_VS_SOCIAL_REG_RESP_BYTES, NULL,
                       cloud_file_sink, &sink);

  close(sink.fd);
  sink.fd = -1;

  /* The sink's own reason wins over the transport's, which has collapsed it
   * into one code by now.
   */

  if (sink.over)
    {
      printf("%s: download exceeds the %zu byte budget\n", CLOUD_TAG,
             max_bytes);
      ret = -EFBIG;
      goto unlink_out;
    }

  if (sink.err != 0)
    {
      printf("%s: writing %s failed: %d\n", CLOUD_TAG, path, sink.err);
      ret = -sink.err;
      goto unlink_out;
    }

  if (http < 0)
    {
      /* How far it got is the whole diagnosis.  Zero means the request never
       * produced a body -- a refused connection, a bad URL, an expired
       * signature.  A partial count means the transfer started and then the
       * peer or the link gave up, which is a different problem with a
       * different fix, and without the number here the two look identical.
       */

      printf("%s: download of %s failed after %zu bytes: %d\n", CLOUD_TAG,
             path, sink.written, http);
      ret = http;
      goto unlink_out;
    }

  if (http < 200 || http >= 300)
    {
      printf("%s: download returned HTTP %d after %zu bytes\n", CLOUD_TAG,
             http, sink.written);
      ret = -EIO;
      goto unlink_out;
    }

  if (sink.written == 0)
    {
      ret = -ENODATA;
      goto unlink_out;
    }

  if (len != NULL)
    {
      *len = sink.written;
    }

  ret = 0;
  goto out;

unlink_out:

  /* Leave nothing playable behind.  A partial WAV on disk would be picked up
   * by the next attempt to play one and sound like a hardware fault.
   */

  unlink(path);
"}

{"content":" * Long enough not to pre-empt a slow but working cloud: an upload sits behind
 * CONFIG_VS_SOCIAL_IO_TIMEOUT_MS.  This is the outer bound, after which the UI
 * stops waiting and says so.
 */

#define VS_SOCIAL_STAGE_TIMEOUT_MS 40000

#ifndef CONFIG_VS_SOCIAL_FINALIZE_TIMEOUT_MS
#  define CONFIG_VS_SOCIAL_FINALIZE_TIMEOUT_MS 60000
#endif

/* Finalizing is the exception, and its bound has to be derived rather than
 * chosen.  That page's worker is allowed CONFIG_VS_SOCIAL_FINALIZE_TIMEOUT_MS
 * to poll for minutes, so a fixed number here silently becomes the inner bound
 * the moment the worker's is raised past it.
 *
 * Which is exactly what happened.  The worker's budget went from 30 s to 60 s
 * to cover a cloud measured taking 24 s to produce minutes; this stayed at 40 s.
 * Measured 2026-09-04, a session that closed at t+213.6 was aborted by this
 * timer at t+249.8 -- 40 s after entering the page -- while the worker was
 * still polling and had 20 s of its own budget left.  The user got "社交记录
 * 整理无响应" for a cloud that was merely slow, the minutes never arrived, and
 * the worker's own specific failure was unreachable by construction.
 *
 * Expressed as the worker's budget plus a margin, the ordering is a property of
 * the code rather than a note asking the next person to remember it.  The margin
 * covers the poll interval plus the two downloads that follow a successful
 * poll, which happen before the page is left.
 */

#define VS_SOCIAL_FINALIZE_STAGE_TIMEOUT_MS \
  (CONFIG_VS_SOCIAL_FINALIZE_TIMEOUT_MS + 20000)
#define VS_WIFI_RETRY_MS 20000

#define VS_APP_EVENT_QUEUE_SIZE 8

static struct
{
