       * mode has to say AP even though no mode change was requested.
       */

      runtime->error_target_mode = VS_NET_AP;
      runtime->progress = 0;
      vs_set_error_reason(runtime, ret, VS_PAGE_SOFTAP, true, "热点密码重置");"}

