 * clamps at both ends, the streak reset, and a recovery step that must not
 * undershoot the configured ceiling.
 */
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>

#define CONFIG_VS_SOCIAL_IMAGE_INTERVAL_MS      500
#define CONFIG_VS_SOCIAL_IMAGE_INTERVAL_MAX_MS 2000
#define SOCIAL_IMAGE_RECOVER_STREAK   4
#define SOCIAL_IMAGE_RECOVER_STEP_MS 250u

static int failures;
#define CHECK(c, w) do { if (c) printf("  ok    %s\n", w); \
  else { printf("  FAIL  %s\n", w); failures++; } } while (0)

static uint32_t interval;
static uint32_t streak;

static void reset(void) { interval = CONFIG_VS_SOCIAL_IMAGE_INTERVAL_MS; streak = 0; }

/* verbatim from social_image_push() */
static void on_drop(void)
{
  streak = 0;
  if (interval < CONFIG_VS_SOCIAL_IMAGE_INTERVAL_MAX_MS)
    {
      uint32_t next = interval * 2u;
      if (next > CONFIG_VS_SOCIAL_IMAGE_INTERVAL_MAX_MS)
        next = CONFIG_VS_SOCIAL_IMAGE_INTERVAL_MAX_MS;
      interval = next;
    }
}

/* verbatim from the upload worker's success path, is_image gating included */
static void on_upload_ok(bool is_image)
{
  if (is_image && interval > CONFIG_VS_SOCIAL_IMAGE_INTERVAL_MS &&
      ++streak >= SOCIAL_IMAGE_RECOVER_STREAK)
    {
      uint32_t next = interval;
      streak = 0;
      next = next > SOCIAL_IMAGE_RECOVER_STEP_MS +
                    CONFIG_VS_SOCIAL_IMAGE_INTERVAL_MS ?
             next - SOCIAL_IMAGE_RECOVER_STEP_MS :
             CONFIG_VS_SOCIAL_IMAGE_INTERVAL_MS;
      interval = next;
    }
}

int main(void)
{
  int i;

  puts("backoff");
  reset();
  CHECK(interval == 500, "starts at the configured ceiling, 2 fps");
  on_drop(); CHECK(interval == 1000, "one drop halves the rate to 1 fps");
  on_drop(); CHECK(interval == 2000, "two drops reach the 0.5 fps floor");
  on_drop(); CHECK(interval == 2000, "further drops do not go below 0.5 fps");
  for (i = 0; i < 20; i++) on_drop();
  CHECK(interval == CONFIG_VS_SOCIAL_IMAGE_INTERVAL_MAX_MS,
        "a sustained stall stays clamped at the floor");

  puts("\nrecovery");
  reset(); on_drop(); on_drop();          /* at 2000 */
  for (i = 0; i < 3; i++) on_upload_ok(true);
  CHECK(interval == 2000, "three clean frames are not yet a run");
  on_upload_ok(true);
  CHECK(interval == 1750, "the fourth earns one 250 ms step");
  for (i = 0; i < 4; i++) on_upload_ok(true);
  CHECK(interval == 1500, "and each further run earns another");

  puts("\nrecovery cannot overshoot the ceiling");
  reset(); on_drop();                     /* 1000 */
  for (i = 0; i < 4; i++) on_upload_ok(true);
  CHECK(interval == 750, "1000 steps to 750");
  for (i = 0; i < 4; i++) on_upload_ok(true);
  CHECK(interval == 500, "750 lands exactly on the ceiling, not 500-250");
  for (i = 0; i < 40; i++) on_upload_ok(true);
  CHECK(interval == 500, "at the ceiling further successes change nothing");

  puts("\nfull round trip");
  reset();
  for (i = 0; i < 5; i++) on_drop();
  CHECK(interval == 2000, "floor reached");
  for (i = 0; i < 200; i++) on_upload_ok(true);
  CHECK(interval == 500, "a long clean run returns all the way to 2 fps");

  puts("\nthe streak resets");
  reset(); on_drop(); on_drop();
  on_upload_ok(true); on_upload_ok(true); on_upload_ok(true);
  CHECK(streak == 3, "three banked");
  on_drop();
  CHECK(streak == 0, "a drop clears the run");
  on_upload_ok(true); on_upload_ok(true); on_upload_ok(true);
  CHECK(interval == 2000, "so three more still do not earn a step");
  on_upload_ok(true);
  CHECK(interval == 1750, "the fourth after the reset does");

  puts("\naudio does not credit the image sampler");
  reset(); on_drop(); on_drop();
  for (i = 0; i < 40; i++) on_upload_ok(false);
  CHECK(interval == 2000 && streak == 0,
        "audio uploads never speed the sampler back up");
  for (i = 0; i < 4; i++) on_upload_ok(true);
  CHECK(interval == 1750, "only images do");

  puts("\ninvariants over a random walk");
  {
    uint32_t lo = 9999, hi = 0;
    unsigned seed = 12345;

    reset();
    for (i = 0; i < 20000; i++)
      {
        seed = seed * 1103515245u + 12345u;
        if ((seed >> 16) % 3 == 0) on_drop(); else on_upload_ok(true);
        if (interval < lo) lo = interval;
        if (interval > hi) hi = interval;
        if (interval < CONFIG_VS_SOCIAL_IMAGE_INTERVAL_MS ||
            interval > CONFIG_VS_SOCIAL_IMAGE_INTERVAL_MAX_MS)
          { printf("  FAIL  left the range at step %d: %u\n", i, interval);
            failures++; break; }
      }
    CHECK(lo >= CONFIG_VS_SOCIAL_IMAGE_INTERVAL_MS &&
          hi <= CONFIG_VS_SOCIAL_IMAGE_INTERVAL_MAX_MS,
          "20000 mixed events never leave [500, 2000]");
    printf("    (observed %u..%u ms, i.e. %.2f..%.2f fps)\n", lo, hi,
           1000.0 / hi, 1000.0 / lo);
  }

  printf("\n%s (%d failure%s)\n", failures ? "FAIL" : "PASS", failures,
         failures == 1 ? "" : "s");
  return failures != 0;
}
